    "8":[{"t": "Lineare Funktionen", "d": "Geraden, Steigung, Nullstellen.", "l": "M8 1.1", "f": [["Funktionsgleichung", "y = m·x + t"], ["Steigung m", "Änderung von y pro x"], ["Nullstelle", "x-Wert mit y = 0"]], "q": [{"k": "num", "q": "y = 2x + 1. y für x = 3?", "a": 7, "e": "2·3+1 = 7."}, {"k": "num", "q": "y = 3x − 6. Nullstelle bei x = ?", "a": 2, "e": "3x−6=0 → x=2."}, {"k": "mc", "q": "Steigung von y = −x + 4?", "o": ["4", "−1", "1", "0"], "c": 1, "e": "Faktor vor x ist −1."}]}, {"t": "Lineare Gleichungssysteme", "d": "Zwei Gleichungen, zwei Variablen.", "l": "M8 1.2", "f": [["Einsetzungsverfahren", "eine Variable ersetzen"], ["Gleichsetzungsverfahren", "Terme gleichsetzen"], ["Additionsverfahren", "Gleichungen addieren"]], "q": [{"k": "num", "q": "x+y=10 und x−y=4. x?", "a": 7, "e": "2x = 14 → x = 7."}]}, {"t": "Potenzen und Bruchterme", "d": "Potenzen mit ganzzahligen Exponenten.", "l": "M8 1.3", "f": [["a^m · a^n", "= a^(m+n)"], ["(a^m)^n", "= a^(m·n)"], ["a^(−n)", "= 1/a^n"]], "q": [{"k": "num", "q": "2³ · 2² = ?", "a": 32, "e": "2^5 = 32."}, {"k": "num", "q": "3^(−2) als Bruch – Nenner?", "a": 9, "e": "1/9."}]}, {"t": "Kreis und Zylinder", "d": "Umfang, Fläche, Volumen.", "l": "M8 1.4", "f": [["Kreisumfang", "U = 2·π·r"], ["Kreisfläche", "A = π·r²"], ["Zylindervolumen", "V = π·r²·h"]], "q": [{"k": "num", "q": "Kreis r=5 cm: Fläche (π≈3,14)?", "a": 78.5, "e": "3,14·25 = 78,5."}, {"k": "num", "q": "Kreis d=10 cm: Umfang (π≈3,14)?", "a": 31.4, "e": "3,14·10 = 31,4."}]}, {"t": "Wahrscheinlichkeit", "d": "Laplace-Experimente.", "l": "M8 1.5", "f": [["Laplace", "alle Ergebnisse gleich wahrscheinlich"], ["P(Ereignis)", "günstige / mögliche Ergebnisse"]], "q": [{"k": "mc", "q": "P(6) beim Würfel?", "o": ["1/2", "1/3", "1/6", "1/12"], "c": 2, "e": "1 von 6."}]}],
