    "10":[{"t": "Exponentialfunktionen und Wachstum", "d": "Exponentielles Wachstum, Zinseszins, Zerfall.", "l": "M10 1.1", "f": [["Exponentialfunktion", "y = a · b^x"], ["Wachstumsfaktor", "b > 1 wächst, 0 < b < 1 zerfällt"], ["Zinseszins", "K = K₀ · (1+p)^n"]], "q": [{"k": "num", "q": "100 € zu 5 % für 2 Jahre (Zinseszins)?", "a": 110.25, "e": "100·1,05² = 110,25 €."}]}, {"t": "Kreis und Körper", "d": "Kugel, Kegel, zusammengesetzte Körper.", "l": "M10 1.2", "f": [["Kugelvolumen", "V = 4/3 · π · r³"], ["Kegelvolumen", "V = 1/3 · π · r² · h"]]}, {"t": "Pythagoras im Raum", "d": "Raumdiagonale und Abstände.", "l": "M10 1.3", "f": [["Raumdiagonale", "d² = a² + b² + c²"], ["Flächendiagonale", "d² = a² + b²"]]}, {"t": "Zufall und Wahrscheinlichkeit", "d": "Baumdiagramme, mehrstufige Experimente.", "l": "M10 1.4", "f": [["Pfadregel", "Wahrscheinlichkeiten entlang eines Pfades multiplizieren"], ["Summenregel", "Wahrscheinlichkeiten mehrerer Pfade addieren"]], "q": [{"k": "num", "q": "Zweimal Würfeln: P(2× Sechs) als Bruch – Nenner?", "a": 36, "e": "1/6 · 1/6 = 1/36."}]}, {"t": "Funktionen und Modellieren", "d": "Funktionen anwenden, Sachaufgaben.", "l": "M10 1.5", "f": [["Modell", "vereinfachte Abbildung der Wirklichkeit"], ["Sachaufgabe", "Anwendung in Alltagskontext"]]}]
